INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q1639459', 'Battle of Mu''tah', 'The Battle of Mu''tah (Arabic: مَعْرَكَة مُؤْتَة, romanized: Maʿrakat Muʿtah, or Arabic: غَزْوَة مُؤْتَة Ghazwat Muʿtah) took place in September 629 (1 Jumada al-Awwal 8 AH), between the forces of Muhammad and the army of the Byzantine Empire and their Ghassanid vassals. It took place in the village of Mu''tah in Palaestina Salutaris at the east of the Jordan River and modern-day Karak.', 629, NULL, NULL, NULL, NULL, NULL, 'year', '629', 72, 'https://en.wikipedia.org/wiki/Battle_of_Mu''tah'),
  ('Q1030249', 'Battle of Fahl', 'The Battle of Fahl (Arabic: يوم فحل, romanized: Yawm Faḥl), also known as the Battle of the Marshes (Yawm al-Radagha) and the Battle of Beisan (Yawm Baysān), was a major battle in the Muslim conquest of Byzantine Syria fought by the Arab troops of the Rashidun Caliphate and Byzantine forces at or near Pella (Fahl) and nearby Scythopolis (Beisan), both in the Jordan Valley, in December 634 or January 635. Byzantine troops smarting from their rout by the Muslims at the battle of Ajnadayn had regrouped in Pella or Scythopolis and the Muslims pursued them there.', 635, 1, NULL, NULL, NULL, NULL, 'month', 'January 635', 58, 'https://en.wikipedia.org/wiki/Battle_of_Fahl'),
  ('Q126959950', 'Siege of Ayla', 'The siege of Ayla was a military engagement between the troops of Saladin and the Crusader fortress in Ayla (modern-day Aqaba). Saladin successfully captured Ayla from the Crusaders.', 1170, 12, 31, NULL, NULL, NULL, 'day', '31 December 1170', 34, 'https://en.wikipedia.org/wiki/Siege_of_Ayla'),
  ('Q815156', 'Siege of Kerak', 'Kerak Castle, one of the most impregnable strongholds in the Kingdom of Jerusalem, underwent its first significant siege in late 1183. Saladin, ruler of Egypt and Damascus, besieged Kerak in early November 1183 after its lord, Raynald of Châtillon, conducted raids of Saladin''s lands.', 1183, 11, NULL, 1183, 12, 4, 'month', 'November 1183 – 4 December 1183', 52, 'https://en.wikipedia.org/wiki/Siege_of_Kerak_(1183)'),
  ('Q2081944', 'Battle of Aqaba', 'The Battle of Aqaba was fought for the Red Sea port of Aqaba (now in Jordan) during the Arab Revolt of World War I. The attacking forces, led by Sherif Nasir and Auda abu Tayi and advised by T. E. Lawrence ("Lawrence of Arabia"), were victorious over the Ottoman Empire defenders.', 1917, 7, 6, NULL, NULL, NULL, 'day', '6 July 1917', 55, 'https://en.wikipedia.org/wiki/Battle_of_Aqaba'),
  ('Q4871340', 'Battle of Jisr Benat Yakub', 'The Battle of Jisr Benat Yakub was fought on 27 September 1918 at the beginning of the pursuit by the Desert Mounted Corps of the retreating remnants of the Yildirim Army Group towards Damascus during the Sinai and Palestine campaign of World War I. After the Battle of Samakh and the Capture of Tiberias, which completed the Egyptian Expeditionary Force''s decisive victory in the Battle of Sharon section of the Battle of Megiddo, the Australian Mounted Division attacked and captured a series of rearguard positions. The positions were held by German and Ottoman soldiers of the Tiberias Group…', 1918, 9, 27, NULL, NULL, NULL, 'day', '27 September 1918', 37, 'https://en.wikipedia.org/wiki/Battle_of_Jisr_Benat_Yakub'),
  ('Q5452498', 'First Battle of Amman', 'The First Battle of Amman was fought from 27 to 31 March 1918 during the First Transjordan attack on Amman of the Sinai and Palestine Campaign of the First World War. The 60th (London) Division and the Anzac Mounted Division attacked the Ottoman garrison at Amman deep in enemy occupied territory, 48 kilometres (30 mi) from their front line, after capturing Es Salt and Shunet Nimrin.', 1918, 3, 27, 1918, 3, 31, 'day', '27 March 1918 – 31 March 1918', 37, 'https://en.wikipedia.org/wiki/First_Battle_of_Amman'),
  ('Q7443068', 'Second Battle of Amman', 'The Second Battle of Amman was fought on 25 September 1918 during the Third Transjordan attack as part of the Battle of Nablus which together with the main Battle of Sharon form the major set piece offensive known as the Battle of Megiddo of the Sinai and Palestine Campaign in World War I. After cutting the road from Nablus to Es Salt on 22 September Chaytor''s Force captured the bridge over the Jordan River at Jisr ed Damieh while units of the Seventh Army and remnants of the Eighth Army were still in retreating towards the bridge from the Judean Hills. Having cut this line of retreat,…', 1918, 9, 25, NULL, NULL, NULL, 'day', '25 September 1918', 37, 'https://en.wikipedia.org/wiki/Second_Battle_of_Amman'),
  ('Q49097', '1948 Palestine war', 'The 1948 Palestine war (30 November 1947 – 10 March 1949), known in Palestine as the Nakba and in Israel as the War of Independence, was fought in the territory of what had been, at the start of the war, British-ruled Mandatory Palestine. It began as a civil war between the Arab and Jewish communities following the United Nations Partition Plan and became an international conflict with the Declaration of the Establishment of the State of Israel, the termination of the British mandate, and the entry of the armies of neighbouring Arab states into Palestine.', 1940, NULL, NULL, 1949, 7, 20, 'decade', '1940s – 20 July 1949', 79, 'https://en.wikipedia.org/wiki/1948_Palestine_war'),
  ('Q12406957', 'Battle of Gesher', 'The Battle of Gesher was an attempted joint Iraqi-Jordanian advance against the newly created State of Israel during the 1948 Arab-Israeli War. The battle began on May 14, 1948, when the Jewish exclave of Naharayim was stormed by Arab forces in an attempt to reach the town of Afula and link with the First Yarmouk Brigade of the Arab Liberation Army.', 1948, 5, 14, 1948, 5, 22, 'day', '14 May 1948 – 22 May 1948', 37, 'https://en.wikipedia.org/wiki/Battle_of_Gesher'),
  ('Q2904516', 'War over Water', 'The War over Water, also known as the Battle over Water, was a series of confrontations between Israel and its Arab neighbors from November 1964 to May 1967 over control of water sources in the Jordan River drainage basin.', 1964, 11, NULL, 1967, 5, NULL, 'month', 'November 1964 – May 1967', 37, 'https://en.wikipedia.org/wiki/War_over_Water_(Jordan_River)'),
  ('Q49077', 'Six-Day War', 'The Six-Day War, or the 1967 Arab–Israeli war (5–10 June 1967), was fought between Israel and a coalition of six Arab states, primarily Egypt, Syria, and Jordan, in the context of the Arab–Israeli conflict. The war, in which Israel conquered and occupied the Sinai Peninsula, the Gaza Strip, the West Bank of the Jordan River, East Jerusalem, and the Golan Heights, shaped the political and strategic landscape of the Middle East into the 21st century.', 1967, 6, 5, 1967, 6, 10, 'day', '5 June 1967 – 10 June 1967', 89, 'https://en.wikipedia.org/wiki/Six-Day_War'),
  ('Q322607', 'War of Attrition', 'The War of Attrition (Arabic: حرب الاستنزاف, romanized: Ḥarb al-Istinzāf; Hebrew: מלחמת ההתשה, romanized: Milḥemet haHatashah) involved fighting between Israel and Egypt, Jordan, the Palestine Liberation Organisation (PLO) and their allies from 1967 to 1970. Following the 1967 Six-Day War, no serious diplomatic efforts were made to resolve the issues at the heart of the Arab–Israeli conflict.', 1967, 7, 1, 1970, 8, 7, 'day', '1 July 1967 – 7 August 1970', 73, 'https://en.wikipedia.org/wiki/War_of_Attrition'),
  ('Q2336243', 'Battle of Ammunition Hill', 'Ammunition Hill (Hebrew: גִּבְעַת הַתַּחְמֹשֶׁת, Giv''at HaTahmoshet) was a fortified Jordanian military post in the northern part of Jordanian-ruled East Jerusalem and the western slope of Mount Scopus. It was the site of one of the fiercest battles of the Six-Day War.', 1967, 6, 6, NULL, NULL, NULL, 'day', '6 June 1967', 45, 'https://en.wikipedia.org/wiki/Battle_of_Ammunition_Hill'),
  ('Q1930278', 'Battle of Karameh', 'The Battle of Karameh (Arabic: معركة الكرامة) was a 15-hour military engagement between Israel and the combined forces of Jordan and the Palestine Liberation Organization (PLO) in the Jordanian border town of Karameh during the War of Attrition on 21 March 1968. It was planned by Israel as one of two concurrent raids on PLO camps, one in Karameh along the Jordan River and the other in the distant village of Ghor es-Safi south of the Dead Sea.', 1968, 3, 21, NULL, NULL, NULL, 'day', '21 March 1968', 61, 'https://en.wikipedia.org/wiki/Battle_of_Karameh'),
  ('Q154288', 'Black September', 'Black September (Arabic: أيلول الأسود, romanized: Aylūl al-ʾAswad), also known as the Jordanian Civil War, was an armed conflict between Jordan, led by King Hussein, and the Palestine Liberation Organization (PLO), led by chairman Yasser Arafat. The main phase of the fighting took place between 16 and 27 September 1970, though certain aspects of the conflict continued until 17 July 1971.', 1970, 9, 6, 1971, 7, 17, 'day', '6 September 1970 – 17 July 1971', 73, 'https://en.wikipedia.org/wiki/Black_September'),
  ('Q131550806', 'Syrian invasion of Jordan', 'The Syrian invasion of Jordan began on 18 September 1970 in support of the Palestine Liberation Organization (PLO) amid Black September. Syria conducted a short-lived incursion toward Irbid in northern Jordan, before being forced to withdraw due to heavy casualties.', 1970, 9, 18, 1970, 9, 23, 'day', '18 September 1970 – 23 September 1970', 30, 'https://en.wikipedia.org/wiki/Syrian_invasion_of_Jordan'),
  ('Q6083589', 'Island of Peace massacre', 'The Island of Peace massacre was a high-profile shooting attack that took place on 13 March 1997, when a Jordanian soldier opened fire on a group of young Israeli schoolgirls and their teacher at the Island of Peace. Seven of the girls were killed, while five more and the teacher were injured; all of the girls in the group were aged 13–14.', 1997, 3, 13, NULL, NULL, NULL, 'day', '13 March 1997', 43, 'https://en.wikipedia.org/wiki/Island_of_Peace_massacre'),
  ('Q255997', 'Houthi insurgency', 'The Houthi insurgency, also known as the Sa''dah Wars, was a military rebellion pitting Zaidi Shia Houthis that began in northern Yemen and has since escalated into a full-scale civil war. The conflict was sparked in 2004 by the government''s attempt to arrest Hussein al-Houthi, a Zaidi religious leader of the Houthis and a former parliamentarian on whose head the government had placed a $55,000 bounty.', 2015, 2, 6, NULL, NULL, NULL, 'day', '6 February 2015', 63, 'https://en.wikipedia.org/wiki/Houthi_insurgency'),
  ('Q54801062', 'Jordan Protests, May-June 2018', 'The 2018 Jordanian protests started as a general strike organized by more than 30 trade unions on 30 May 2018 after the government of Hani Mulki submitted a new tax law to Parliament. The bill followed IMF-backed austerity measures adopted by Mulki''s government since 2016 that aimed to tackle Jordan''s growing public debt.', 2018, NULL, NULL, NULL, NULL, NULL, 'year', '2018', 41, 'https://en.wikipedia.org/wiki/2018_Jordanian_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q123124528', 'attacks on US bases during the Gaza war', 'Starting on 17 October 2023, and in response to United States support for Israel in the Gaza war, Iran-backed militias initiated a coordinated series of more than 170 attacks on US military bases and assets in Syria, Iraq, and Jordan. These attacks resulted in injuries to dozens of US service members.', 2023, 10, 18, 2024, 2, 4, 'day', '18 October 2023 – 4 February 2024', 51, 'https://en.wikipedia.org/wiki/Attacks_on_US_bases_during_the_Middle_Eastern_crisis_(2023%E2%80%93present)');
